import unittest

from hourglass.rounding import label_span, round_labels
from hourglass.rounding import round_span
from hourglass.models import Span

class RoundingTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            label_span(Span(540, 1035)),
            "09:00-17:15 (8h 15m)"
        )

    def test_snaps_to_nearest_step(self):
        result = round_labels([Span(543, 1032)], 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_halfway_goes_up(self):
        snapped = round_span(Span(5, 100), 10)
        self.assertEqual(snapped, Span(10, 100))

    def test_just_under_halfway_goes_down(self):
        snapped = round_span(Span(4, 104), 10)
        self.assertEqual(snapped, Span(0, 100))

    def test_many_spans_in_order(self):
        spans = [Span(481, 600), Span(610, 1440)]
        self.assertEqual(
            round_labels(spans, 30),
            ["08:00-10:00 (2h 0m)", "10:00-24:00 (14h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)

    def test_bad_step_raises_even_when_empty(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(541, 544)], 15)
